        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by using an incorrect string key `"perio"` instead of the correct key `"period"` when retrieving the frequency choice from a tree node. This likely led to the GUI not properly activating writers based on the specified formula, as it was unable to find the correct tag associated with the frequency setting.

        Commit message:
        GUI : fix bug in writers activation by formula introduced in
 commit b756face  

        Patch:

 void
 cs_gui_postprocess_activate(void)
 {
   const char path_o[] = "analysis_control/output";
   cs_tree_node_t *tn_o = cs_tree_get_node(cs_glob_tree, path_o);

   for (cs_tree_node_t *tn = cs_tree_get_node(tn_o, "writer");
        tn != NULL;
        tn = cs_tree_node_get_next_of_name(tn)) {

     const int *v_i = cs_tree_node_get_child_values_int(tn, "id");
     if (v_i == NULL) continue;

     int id = v_i[0];

     const char *frequency_choice
       = cs_tree_node_get_tag(cs_tree_node_get_child(tn, "frequency"),
-                             "perio");
+                             "period");

     if (cs_gui_strcmp(frequency_choice, "formula")) {
       const char *formula = cs_tree_node_get_child_value_str(tn, "frequency");
       assert(formula != NULL);
       const cs_time_step_t *ts = cs_glob_time_step;
       mei_tree_t *ev_formula = _init_mei_tree(formula, ts->nt_cur, ts->t_cur);
       mei_evaluate(ev_formula);
       int iactive =  mei_tree_lookup(ev_formula, "iactive");
       mei_tree_destroy(ev_formula);
       if (iactive == 1)
         cs_post_activate_writer(id, true);
       else
         cs_post_activate_writer(id, false);
     }

   }
 }



